ALTER TABLE sys_plan ADD COLUMN automation_enabled boolean NOT NULL DEFAULT true,ADD COLUMN automation_rule_limit int NOT NULL DEFAULT 20 CHECK(automation_rule_limit BETWEEN 0 AND 1000),ADD COLUMN automation_monthly_limit int NOT NULL DEFAULT 5000 CHECK(automation_monthly_limit BETWEEN 0 AND 1000000);
CREATE TABLE crm_automation_rule(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,name varchar(100) NOT NULL,entity_type varchar(30) NOT NULL,trigger_type varchar(20) NOT NULL CHECK(trigger_type IN('CONDITION','SCHEDULE','MANUAL')),owner_member_id uuid NOT NULL,created_by_member_id uuid NOT NULL,owner_auth_version bigint NOT NULL,creator_auth_version bigint NOT NULL,definition jsonb NOT NULL,status varchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','ACTIVE','PAUSED')),published_version bigint,published_at timestamptz,schedule_day date,schedule_cursor uuid,schedule_complete boolean NOT NULL DEFAULT false,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,owner_member_id) REFERENCES sys_tenant_member(tenant_id,id),FOREIGN KEY(tenant_id,created_by_member_id) REFERENCES sys_tenant_member(tenant_id,id));
CREATE TABLE crm_automation_revision(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,rule_id uuid NOT NULL,business_version bigint NOT NULL,snapshot jsonb NOT NULL,actor_member_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,rule_id,business_version),FOREIGN KEY(tenant_id,rule_id) REFERENCES crm_automation_rule(tenant_id,id));
CREATE TABLE crm_automation_event(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,entity_type varchar(30) NOT NULL,entity_id uuid NOT NULL,business_version bigint NOT NULL,origin_depth int NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,UNIQUE(tenant_id,id),UNIQUE(tenant_id,entity_type,entity_id,business_version));
CREATE INDEX automation_event_pending ON crm_automation_event(tenant_id,created_at,id) WHERE processed_at IS NULL;
CREATE TABLE crm_automation_run(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,rule_id uuid NOT NULL,rule_version bigint NOT NULL,entity_id uuid NOT NULL,trigger_key varchar(160) NOT NULL,status varchar(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','RETRY','SUCCESS','SKIPPED','BLOCKED','DEAD')),attempts int NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5),next_attempt_at timestamptz NOT NULL DEFAULT now(),error_code varchar(80),results jsonb,created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,UNIQUE(tenant_id,id),UNIQUE(tenant_id,rule_id,rule_version,entity_id,trigger_key),FOREIGN KEY(tenant_id,rule_id) REFERENCES crm_automation_rule(tenant_id,id));
CREATE INDEX automation_run_pending ON crm_automation_run(tenant_id,next_attempt_at,id) WHERE status IN('PENDING','RETRY');
CREATE TABLE crm_automation_attempt(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,run_id uuid NOT NULL,attempt_no int NOT NULL,outcome varchar(20) NOT NULL,error_code varchar(80),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,run_id,attempt_no),FOREIGN KEY(tenant_id,run_id) REFERENCES crm_automation_run(tenant_id,id));
CREATE FUNCTION crm_capture_automation() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF TG_OP='UPDATE' AND NEW.version=OLD.version THEN RETURN NEW;END IF;
 IF coalesce(nullif(current_setting('crm.automation_depth',true),''),'0')::int>0 OR NOT EXISTS(SELECT 1 FROM crm_automation_rule WHERE tenant_id=NEW.tenant_id AND entity_type=TG_ARGV[0] AND trigger_type='CONDITION' AND status='ACTIVE') THEN RETURN NEW;END IF;
 INSERT INTO crm_automation_event(id,tenant_id,entity_type,entity_id,business_version,origin_depth) VALUES(gen_random_uuid(),NEW.tenant_id,TG_ARGV[0],NEW.id,NEW.version,coalesce(nullif(current_setting('crm.automation_depth',true),''),'0')::int) ON CONFLICT DO NOTHING;RETURN NEW;
END$$;
DO $$DECLARE n text;et text;BEGIN
 FOR n,et IN SELECT * FROM(VALUES('crm_customer','CUSTOMER'),('crm_lead','LEAD'),('crm_opportunity','OPPORTUNITY'),('crm_quote','QUOTE'),('crm_sales_order','ORDER'),('crm_contract','CONTRACT'),('crm_receipt','RECEIPT'),('crm_ticket','TICKET'),('crm_invoice','INVOICE'),('crm_expense','EXPENSE'),('crm_sales_target','TARGET'),('crm_commission_run','COMMISSION'),('crm_sales_weekly_report','WEEKLY'),('crm_product','PRODUCT')) v(n,et) LOOP EXECUTE format('CREATE TRIGGER automation_capture AFTER INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION crm_capture_automation(%L)',n,et);END LOOP;
 FOREACH n IN ARRAY ARRAY['crm_automation_rule','crm_automation_revision','crm_automation_event','crm_automation_run','crm_automation_attempt'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',n);EXECUTE format('CREATE POLICY tenant_boundary ON %I USING(tenant_id=nullif(current_setting(''crm.tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=nullif(current_setting(''crm.tenant_id'',true),'''')::uuid)',n);END LOOP;
END$$;
GRANT SELECT,INSERT,UPDATE ON crm_automation_rule,crm_automation_event,crm_automation_run TO crm_runtime;
GRANT SELECT,INSERT ON crm_automation_revision,crm_automation_attempt TO crm_runtime;
